Section EQ.
  Context {HCEIL : HeapCeil}.

Definition AEQ_STACK : Z := 32.

Definition eq_post_v (v : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P Q lo : Z) (bs cs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (if v then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ bytes_at asegs m' P bs /\ bytes_at asegs m' Q cs
    /\ ACONST m' /\ accessible m' P (Z.of_nat (length bs)) /\ accessible m' Q (Z.of_nat (length cs)).

Definition equals_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P Q lo : Z) (bs cs : list byte) (m : mem) : machine_state -> Prop :=
  eq_post_v (ft_ieqb (zbytes bs) (zbytes cs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P Q lo bs cs m.

Definition equals_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P Q lo : Z) (bs cs : list byte),
  bytes_at asegs m P bs -> bytes_at asegs m Q cs ->
  P + Z.of_nat (length bs) < 2^64 -> Q + Z.of_nat (length cs) < 2^64 ->
  stk asegs m lo (bv_unsigned sp) -> lo + AEQ_STACK <= bv_unsigned sp -> aceil <= lo ->      (* [comment removed for export] *)
  (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo) ->
  (bv_unsigned sp <= Q \/ Q + Z.of_nat (length cs) <= lo) ->
  mem_inv asegs m ->
  (* [comment removed for export] *)
  ACONST m -> accessible m P (Z.of_nat (length bs)) -> accessible m Q (Z.of_nat (length cs)) ->
  evt asegs (equals_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P Q lo bs cs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz (Z.of_nat (length bs))) (wz Q) (wz (Z.of_nat (length cs))) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_FIELD_TABLE_EQUALS) fc None m (seg_rom asegs)).

(* [comment removed for export] *)
Definition eq_side (m : mem) (P n Q k : Z) : Prop := ACONST m /\ accessible m P n /\ accessible m Q k.
Lemma eq_side_now : forall m m1 P n Q k lo hi,
  eq_side m P n Q k -> munch [(lo, hi)]%Z m m1 -> wmono asegs m m1 -> aceil <= lo -> eq_side m1 P n Q k.
Proof.
  intros m m1 P n Q k lo hi (AC & AW & AV) MU WM CEIL.
  assert (FW : Forall awin [(lo, hi)]%Z) by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_nil]).
  split; [eapply aconst_transport_awin; fast_eassumption|]. split; eapply acc_transport_awin; fast_eassumption.
Qed.

Definition eq_ctx (m m1 : mem) (sp s0v s1v s2v rav : word) (P Q lo : Z) (bs cs : list byte) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -32) [C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ bytes_at asegs m1 P bs /\ bytes_at asegs m1 Q cs
  /\ stk asegs m1 lo (bv_unsigned sp + -32)
  /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ eq_side m P (Z.of_nat (length bs)) Q (Z.of_nat (length cs)).

Definition eq_pure (sp : word) (P Q lo : Z) (bs cs : list byte) : Prop :=
  P + Z.of_nat (length bs) < 2^64 /\ Q + Z.of_nat (length cs) < 2^64 /\ lo + AEQ_STACK <= bv_unsigned sp /\ aceil <= lo
  /\ (bv_unsigned sp <= P \/ P + Z.of_nat (length bs) <= lo)
  /\ (bv_unsigned sp <= Q \/ Q + Z.of_nat (length cs) <= lo).

End EQ.

Ltac eq_open CTX PURE :=
  destruct CTX as (FR & WA & WB & ST & MU & WM & MI & SD);
  destruct PURE as (WAE & WBE & LO & CEIL & SEPP & SEPQ);
  pose proof (bytes_at_bound _ _ _ _ WA) as WAB; pose proof (bytes_at_bound _ _ _ _ WB) as WBB;
  pose proof aceil_facts as (AF1 & _);
  hydeL SEPP; hydeL SEPQ;
  unfold AEQ_STACK in *.

(* [comment removed for export] *)
Ltac eq_bchk_gen SD MU WM CEIL SEL a PRE MID JOIN :=
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let AP := fresh "AP" in let AQ := fresh "AQ" in
    let v := fresh "v" in let V1 := fresh "V1" in let V2 := fresh "V2" in let RD := fresh "RD" in
    let w := fresh "w" in
    destruct (eq_side_now _ mc _ _ _ _ _ _ SD MU WM CEIL) as (_ & AP & AQ);
    (lazymatch SEL with
     | true => destruct (accessible_readw_sr mc a 1 (accessible_sub _ _ _ a 1 AP ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(lia)
                 ltac:(clear; Z.div_mod_to_equations; lia)) as (v & V1 & V2 & RD)
     | false => destruct (accessible_readw_sr mc a 1 (accessible_sub _ _ _ a 1 AQ ltac:(lia) ltac:(lia) ltac:(lia)) ltac:(lia)
                 ltac:(clear; Z.div_mod_to_equations; lia)) as (v & V1 & V2 & RD)
     end);
    clear AP AQ;
    PRE; clear RD;
    first [ rewrite (sxb_b8_small v) by (clear - V1; lia) | rewrite (zxb_b8_small v) by (clear - V1; lia) ];
    MID;
    JOIN V1 V2; intros w; clear V1 V2
  end.
Ltac eq_join_ge V1 V2 := shchk_join_ge V1 V2.
Ltac eq_join_lt V1 V2 := shchk_join V1 V2.
Ltac eq_bchk_ge SD MU WM CEIL SEL a PRE MID := eq_bchk_gen SD MU WM CEIL SEL a PRE MID eq_join_ge.
Ltac eq_bchk_lt SD MU WM CEIL SEL a PRE MID := eq_bchk_gen SD MU WM CEIL SEL a PRE MID eq_join_lt.

